def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    fixed = {4, 7}
    mask = ~np.isin(g, list(fixed))
    comps = components(mask)
    cid = {}
    for i, c in enumerate(comps):
        for p in c:
            cid[p] = i
    # clockwise border walk
    path = [(0, x) for x in range(w)] + [(y, w - 1) for y in range(1, h)] \
         + [(h - 1, x) for x in range(w - 2, -1, -1)] + [(y, 0) for y in range(h - 2, 0, -1)]
    order = []
    for p in path:
        if p in cid and cid[p] not in order:
            order.append(cid[p])
    colours = [g[comps[i][0]] for i in order]
    out = g.copy()
    n = len(order)
    for k, i in enumerate(order):
        newc = colours[(k - 1) % n]
        for (y, x) in comps[i]:
            out[y, x] = newc
        emit(out, f"Region originally colour {colours[k]} takes colour {newc} from the previous region clockwise along the border.")
    emit(out, "All border regions have rotated their colours one step clockwise; 4 and 7 stay fixed.")
    return out
